steps.run:
set -euo pipefail
# A re-run by someone else must not publish on the owner's earlier approval.
test "$ACTOR" = "$OWNER" || { echo "run triggered by $ACTOR, not by the repository owner $OWNER" >&2; exit 1; }
test "$PUSHER" = "$OWNER" || { echo "run originally started by $PUSHER, not by the repository owner $OWNER" >&2; exit 1; }
# Drafts are invisible to the verify job's read token; refuse any release, draft or not, for the tag.
existing=$(gh api "repos/$REPO/releases" --paginate --jq ".[] | select(.tag_name == \"$TAG\") | .id")
test -z "$existing" || { echo "a release (possibly a draft) for $TAG already exists: $existing" >&2; exit 1; }
# The tag must still name the verified commit; the owner may have moved it during the run.
remote=$(git ls-remote "https://github.com/$REPO" "refs/tags/$TAG^{}" | cut -f1)
test "$remote" = "$COMMIT" || { echo "tag $TAG now names '$remote', not the verified $COMMIT" >&2; exit 1; }
test "$(git rev-parse HEAD)" = "$COMMIT"
cd "$RUNNER_TEMP/dist"
test "$(ls -1 -- bdock_*.tar.gz | wc -l)" -eq 3 || { echo "expected exactly three archives" >&2; exit 1; }
for platform in darwin_arm64 linux_amd64 linux_arm64; do
  test -f "bdock_${VERSION}_${platform}.tar.gz" || { echo "missing archive for $platform" >&2; exit 1; }
done
cat -- bdock_*.tar.gz.sha256 | LC_ALL=C sort -k2 > SHA256SUMS
test "$(wc -l < SHA256SUMS)" -eq 3 || { echo "expected exactly three checksums" >&2; exit 1; }
sha256sum --check SHA256SUMS
cd "$GITHUB_WORKSPACE"
sh .github/scripts/release-notes.sh "$TAG" "$COMMIT" "$(cat .go-version)" > "$RUNNER_TEMP/notes.md"
test -z "$DRAFT" -o "$DRAFT" = true -o "$DRAFT" = false || { echo "BDOCK_RELEASE_DRAFT must be empty, true or false, got $DRAFT" >&2; exit 1; }
flags=()
if [ "$DRAFT" = true ]; then flags+=(--draft); fi
gh release create "$TAG" --repo "$REPO" --verify-tag --title "bdock v$VERSION" --notes-file "$RUNNER_TEMP/notes.md" ${flags[@]+"${flags[@]}"} \
  "$RUNNER_TEMP"/dist/bdock_*.tar.gz "$RUNNER_TEMP/dist/SHA256SUMS"

set -euo pipefail
test "$(git rev-parse HEAD)" = "$COMMIT" || { echo "checkout is not the verified commit $COMMIT" >&2; exit 1; }
sh .github/scripts/release-smoke.sh "$VERSION" "$COMMIT" "$OS" "$ARCH" "$RUNNER_TEMP/dist/bdock_${VERSION}_${OS}_${ARCH}.tar.gz"

set -euo pipefail
test "$ACTOR" = "$OWNER" || { echo "run started by $ACTOR, not by the repository owner $OWNER" >&2; exit 1; }
test "$PUSHER" = "$OWNER" || { echo "run originally started by $PUSHER, not by the repository owner $OWNER" >&2; exit 1; }

set -euo pipefail
n=$(gh api "repos/$REPO/actions/workflows/ci.yml/runs?head_sha=$GITHUB_SHA&event=push&status=success" --jq '.workflow_runs | map(select(.conclusion == "success")) | length')
test "$n" -ge 1 || { echo "no successful CI run on push for $GITHUB_SHA; wait for or re-run CI for that commit first" >&2; exit 1; }
